        # Check for edge cases
        if n < 2 or m < 2:
            results.append('0')
            continue

        count = 0

        # Check axis-aligned squares
        for r in range(n - 1):
            for c in range(m - 1):
                # Center point
                cr, cc = r, c
                for size in range(2, min(n - r, m - c, r + 1, c + 1)):
                    # Check if all four sides form a valid frame
                    valid = True

                    # Top side: row r, columns c to c + size - 1
                    for j in range(size):
                        if matrix[r][c + j] != '1':
                            valid = False
                            break
                    if not valid:
                        continue

                    # Bottom side: row r + size - 1, columns c to c + size - 1
                    if valid:
                        for j in range(size):
                            if matrix[r + size - 1][c + j] != '1':
                                valid = False
                                break
                        if not valid:
                            continue

                    # Left side: rows r to r + size - 1, column c
                    if valid:
                        for i in range(size):
                            if matrix[r + i][c] != '1':
                                valid = False
                                break
                        if not valid:
                            continue

                    # Right side: rows r to r + size - 1, column c + size - 1
                    if valid:
                        for i in range(size):
                            if matrix[r + i][c + size - 1] != '1':
                                valid = False
                                break
                        if not valid:
                            continue

                    # Corners are covered in top/bottom checks

                    # Check that interior doesn't touch any foreign 1 (must not touch
                    # any 1 except the frame itself)
                    if valid:
                        interior_is_valid = True
                        for i in range(1, size - 1):
                            for j in range(1, size - 1):
                                # Check if this interior point would touch a foreign 1
                                # We need to check the 8 neighbors
                                for di in range(-1, 2):
                                    for dj in range(-1, 2):
                                        ni, nj = r + i + di, c + j + dj
                                        if 0 <= ni < n and 0 <= nj < m:
                                            # Skip if this is part of the frame
                                            if ((ni == r or ni == r + size - 1) and (nj >= c and nj < c + size)) or \
                                               ((nj == c or nj == c + size - 1) and (ni >= r and ni < r + size)):
                                                continue
                                            if matrix[ni][nj] == '1':
                                                interior_is_valid = False
                                                break
                                    if not interior_is_valid:
                                        break
                            if not interior_is_valid:
                                break
                        if interior_is_valid:
                            count += 1

        # Check diamond-shaped squares (rotated 45 degrees)
        for r in range(n):
            for c in range(m):
                # Try all possible sizes of diamond squares
                for size in range(2, min(n, m) + 1):
                    # Diamond square centered at (r, c) with given size
                    # Top vertex at (r - size//2, c)
                    # Left vertex at (r, c - size//2)
                    # Bottom vertex at (r + size//2, c)
                    # Right vertex at (r, c + size//2)

                    half_size = size // 2
                    center_r, center_c = r, c

                    # Check if diamond fits in bounds
                    top_r = center_r - half_size
                    left_c = center_c - half_size
                    bottom_r = center_r + half_size
                    right_c = center_c + half_size

                    if top_r < 0 or left_c < 0 or bottom_r >= n or right_c >= m:
                        continue

                    # Check all border points of the diamond
                    border_valid = True

                    # Top edge: from (top_r, left_c + half_size) to (top_r, right_c - half_size) moving down-left and down-right
                    # Actually, for a diamond of "size" (measured from center to vertex),
                    # we need to trace the border

                    # Let's use a different approach: check the skeleton pattern
                    # A diamond of size k has vertices at distance k from center

                    is_diamond_valid = True

                    # Check all points on the diamond border
                    # Using the diamond shape: |dx| + |dy| = half_size
                    check_r, check_c = top_r, left_c

                    # Walk the diamond border
                    visited_border = set()

                    # Top to left
                    for d in range(1, half_size + 1):
                        nr, nc = top_r + d, center_c
                        if matrix[nr][nc] == '1':
                            visited_border.add(f"{nr},{nc}")
                    for d in range(1, half_size + 1):
                        nr, nc = top_r + d, left_c + d
                        if matrix[nr][nc] == '1':
                            visited_border.add(f"{nr},{nc}")

                    # Left to bottom
                    for d in range(1, half_size + 1):
                        nr, nc = center_r + d, left_c + d
                        if matrix[nr][nc] == '1':
                            visited_border.add(f"{nr},{nc}")

                    # Bottom to right
                    for d in range(1, half_size + 1):
                        nr, nc = bottom_r - d, center_r + d
                        if 0 <= nr < n and 0 <= nc < m:
                            if matrix[nr][nc] == '1':
                                visited_border.add(f"{nr},{nc}")

                    # Right to top
                    for d in range(1, half_size + 1):
                        nr, nc = bottom_r - d, right_c - d
                        if 0 <= nr < n and 0 <= nc < m:
                            if matrix[nr][nc] == '1':
                                visited_border.add(f"{nr},{nc}")

                    # Check all border points exist
                    for d in range(1, half_size + 1):
                        # Point on top-left edge
                        nr, nc = top_r + d, left_c + d
                        if f"{nr},{nc}" not in visited_border:
                            is_diamond_valid = False
                            break

                        # Point on right-left edge
                        nr, nc = bottom_r - d, right_c - d
                        if 0 <= nr < n and 0 <= nc < m and f"{nr},{nc}" not in visited_border:
                            is_diamond_valid = False
                            break

                    if not is_diamond_valid:
                        continue

                    # Check corners exist
                    for corner_r, corner_c in [(top_r, left_c), (bottom_r, right_c),
                                               (top_r, right_c), (bottom_r, left_c)]:
                        if 0 <= corner_r < n and 0 <= corner_c < m:
                            if matrix[corner_r][corner_c] != '1':
                                is_diamond_valid = False
                                break

                    if not is_diamond_valid:
                        continue

                    # Check no foreign 1s touching the diamond
                    no_foreign_1s = True
                    for dr in range(-1, 2):
                        for dc in range(-1, 2):
                            nr, nc = top_r + dr, left_c + dc
                            if 0 <= nr < n and 0 <= nc < m:
                                if matrix[nr][nc] == '1':
                                    # Check if this 1 is part of the diamond border
                                    on_border = False
                                    if ((nr == top_r and left_c <= nc <= right_c and
                                          max(abs(nr - center_r), abs(nc - center_c)) == half_size) or
                                        (nr == center_r and left_c <= nc <= right_c) or
                                        (nc == left_c and top_r <= nr <= bottom_r) or
                                        (nc == right_c and top_r <= nr <= bottom_r) or
                                        (abs(nr - center_r) + abs(nc - center_c) == half_size + 1)):
                                        on_border = False

                    # Simpler: just check each non-border cell in the diamond area
                    for dr in range(-half_size, half_size + 1):
                        for dc in range(-half_size, half_size + 1):
                            nr, nc = center_r + dr, center_c + dc
                            if 0 <= nr < n and 0 <= nc < m:
                                if matrix[nr][nc] == '1':
                                    # This should be part of border
                                    if abs(dr) + abs(dc) != half_size:
                                        no_foreign_1s = False
                                        break

                        if not no_foreign_1s:
                            break

                    if no_foreign_1s:
                        count += 1

        results.append(str(count))

    return '\n'.join(results)

