class SegmentTree:
    def __init__(self, arr):
        self.n = len(arr)
        self.tree = [0] * (4 * self.n)
        self.lazy = [0] * (4 * self.n)

        # Build tree with sum of A[i] * (i+1) for 0-indexed (so position 1 is index 0)
        self.build(arr)

    def build(self, arr):
        self._build_recursive(arr, 0, 0, self.n - 1)

    def _build_recursive(self, arr, node, start, end):
        if start == end:
            self.tree[node] = arr[start] * (start + 1)
            return

        mid = (start + end) // 2
        self._build_recursive(arr, 2 * node + 1, start, mid)
        self._build_recursive(arr, 2 * node + 2, mid + 1, end)
        self.tree[node] = self.tree[2 * node + 1] + self.tree[2 * node + 2]

    def push(self, node, start, end):
        if self.lazy[node] != 0:
            mid = (start + end) // 2

            # Left child range size: mid - start + 1
            left_len = mid - start + 1
            # Right child range size: end - mid
            right_len = end - mid

            self.lazy[2 * node + 1] += self.lazy[node]
            self.tree[2 * node + 1] += self.lazy[node] * (start + 1) * left_len + self.lazy[node] * left_len * (left_len - 1) // 2

            self.lazy[2 * node + 2] += self.lazy[node]
            self.tree[2 * node + 2] += self.lazy[node] * (mid + 1) * right_len

            self.lazy[node] = 0

    def update(self, left, right, val):
        self._update_recursive(0, 0, self.n - 1, left, right, val)
        self._reset_lazy()

    def _update_recursive(self, node, start, end, left, right, val):
        if start > right or end < left:
            return

        if start >= left and end <= right:
            self.lazy[node] += val
            self.tree[node] += val * (start + 1) * (end - start + 1)
            return

        mid = (start + end) // 2
        self._update_recursive(2 * node + 1, start, mid, left, right, val)
        self._update_recursive(2 * node + 2, mid + 1, end, left, right, val)
        self.tree[node] = self.tree[2 * node + 1] + self.tree[2 * node + 2]

    def query(self):
        return self.tree[0]

