import sys

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Store edges with original indices
    edges = []
    for i in range(m):
        parts = lines[i + 1].split()
        u, v, w = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append((u - 1, v - 1, w, i))  # 0-indexed nodes, track original index

    # Sort by weight for MST computation
    sorted_indices = sorted(range(m), key=lambda i: edges[i][2])

    # Kruskal's algorithm to find MST edges
    parent = list(range(n))
    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    mst_adj = [[] for _ in range(n)]
    is_mst_edge = [False] * m

    non_mst_original_indices = []

    for idx in sorted_indices:
        u, v, w, orig_idx = edges[idx]
        if union(u, v):
            is_mst_edge[orig_idx] = True
            mst_adj[u].append((v, w))
            mst_adj[v].append((u, w))
        else:
            non_mst_original_indices.append(orig_idx)

    if not non_mst_original_indices:
        return ""

    # Compute depths using DFS for LCA
    depth = [0] * n
    LOG = n.bit_length()
    up = [[-1] * LOG for _ in range(n)]
    max_up = [[-1] * LOG for _ in range(n)]

    def dfs(u, p=-1, d=0, w=-1):
        depth[u] = d
        up[u][0] = p
        max_up[u][0] = w
        for i in range(1, LOG):
            if up[u][i-1] != -1:
                up[u][i] = up[up[u][i-1]][i-1]
                max_up[u][i] = max(max_up[u][i-1], max_up[up[u][i-1]][i-1])
        for v, _ in mst_adj[u]:
            if v != p:
                dfs(v, u, d + 1, depth[u] * 10 + w)

    for i in range(n):
        dfs(i)

    def get_max(u, v):
        if u == v:
            return 0
        max_w = 0
        # Lift u to find LCA and track max
        while depth[u] > depth[v]:
            diff = depth[u] - depth[v]
            for i in range(LOG):
                if diff & (1 << i):
                    max_w = max(max_w, max_up[u][i])
                    u = up[u][i]
        if u == v:
            return max_w
        for i in range(LOG - 1, -1, -1):
            if up[u][i] != up[v][i]:
                max_w = max(max_w, max_up[u][i], max_up[v][i])
                u = up[u][i]
                v = up[v][i]
        max_w = max(max_w, max_up[u][0])
        return max_w

    result_pieces = []
