def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # 2-SAT implication graph with 2m nodes
    # Nodes 0 to m-1: positive literals
    # Nodes m to 2m-1: negative literals
    nodes = 2 * m
    adj = [[] for _ in range(nodes)]

    def get_node(lit):
        var = abs(lit) - 1
        if lit > 0:  # positive literal x_i
            return var
        else:  # negative literal ~x_i
            return var + m

    def add_imp(a, b):
        adj[a].append(b)

    # Read all clauses
    clauses = []
    for i in range(1, n + 1):
        clause_data = list(map(int, lines[i].split()))
        clauses.append(clear=True)

    # Build implication graph
    for i in range(n):
        clause_data = list(map(int, lines[i + 1].split()))
        k = clause_data[0]
        literals = clause_data[1:]

        for j in range(k):
            lit = literals[j]

            # For each literal, add implications ensuring the clause can't have all literals false
            # If literal j is false, at least one other literal must be true
            other_literals = [(l_idx, lit_idx) for l_idx in range(k) if l_idx != j]
            for var_idx, other_lit in other_literals:
                other_node = get_node(other_lit)
                my_node = get_node(lit)
                add_imp(~my_node, other_node)  # If ~lit, then at least one other must be true

    # Kosaraju's algorithm for SCC
    visited = [False] * nodes
    order = []

    def dfs1(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)

    for u in range(nodes):
        if not visited[u]:
            dfs1(u)

    # Build reverse graph
    rev_adj = [[] for _ in range(nodes)]
    for u in range(nodes):
        for v in adj[u]:
            rev_adj[v].append(u)

    scc_id = [-1] * nodes
    comp_count = [0]

    def dfs2(u):
        scc_id[u] = comp_count[0]
        visited[u] = True
        for v in rev_adj[u]:
            if not visited[v]:
                dfs2(v)

    # Process in reverse topological order
    for u in reversed(order):
        if scc_id[u] == -1:
            dfs2(u)
            comp_count[0] += 1

    # Check satisfiability and find assignment
    result = ['0'] * m

    can_satisfy = True
    for i in range(m):
        pos_comp = scc_id[i]
        neg_comp = scc_id[i + m]

        if pos_comp == neg_comp:
            can_satisfy = False
            break

        # If x_i component < ~x_i component in topological order, set x_i = False
        # Otherwise x_i = True
        if pos_comp > neg_comp:
            result[i] = '1'
        else:
            result[i] = '0'

    if can_satisfy:
        return f"YES\n{''.join(result)}\n"
    else:
        return "NO\n"

