import sys

def compute_grundy(n, k, memo):
    """Compute Grundy number for pile size n with parameter k"""
    if n == 0:
        return 0

    if n in memo:
        return memo[n]

    # Option 1: Remove 1 cow
    moves = {compute_grundy(n - 1, k, memo)}

    # Option 2: Split if n is even
    if n % 2 == 0:
        x = n // 2
        if k % 2 == 1:
            # k piles of size x, XORed = Grundy(x) XORed odd times = Grundy(x)
            moves.add(compute_grundy(x, k, memo))
        else:
            # k piles of size x, XORed = 0 (even number of same values)
            moves.add(0)

    # mex: minimum excludant
    mex = 0
    while mex in moves:
        mex += 1

    memo[n] = mex
    return mex

