def nCr_mod(n, r, MOD):
    if r < 0 or r > n:
        return 0
    if r == 0 or r == n:
        return 1
    fact_n = 1
    fact_r = 1
    fact_nr = 1
    for i in range(1, n + 1):
        fact_n = (fact_n * i) % MOD
    for i in range(1, r + 1):
        fact_r = (fact_r * i) % MOD
    for i in range(1, n - r + 1):
        fact_nr = (fact_nr * i) % MOD
    return (fact_n * inverse(fact_r, MOD) * inverse(fact_nr, MOD)) % MOD

