            if mask & (1 << i):
                for j in range(n):
                    if adj[i][j] == 1:
                        counts[j] += 1
        # Valid if all employees receive a different count than predicted
        return all(counts[j] != a[j] for j in range(n))

    # Try exhaustive search for small n (n <= 20)
    if n <= 20:
        for mask in range(1 << n):
            if check(mask):
                result = []
                for i in range(n):
                    if mask & (1 << i):
