    deltas = {
        'U': (-1, 0),
        'D': (1, 0),
        'L': (0, -1),
        'R': (0, 1)
    }

    # BFS to find shortest path from (0,0) to finish
    queue = deque([(0, 0, "")])
    visited = {(0, 0)}

    while queue:
        r, c, path = queue.popleft()

        if (r, c) == finish:
            return path

        for move in ['U', 'D', 'L', 'R']:
            dr, dc = deltas[move]

            # Apply directional swaps
            if swap_ud and move in ('U', 'D'):
                dr = -dr
