        for x in arr:
            if x % g == 0:
                mark.append(0)
            elif (x - 1) % g == 0 or (x + 1) % g == 0:
                mark.append(1)
            else:
                mark.append(2)

        if 2 in mark:
            continue

        change_cost = sum(b for m in mark if m == 1)
        min_cost = min(min_cost, change_cost)

        prefix = [0] * n
        for i in range(n):
            prefix[i] = prefix[i - 1] if i > 0 else 0
            prefix[i] += (b if mark[i] == 1 else 0)

        suffix = [0] * n
        for i in range(n - 1, -1, -1):
            suffix[i] = (b if mark[i] == 1 else 0
                         + (suffix[i + 1] if i + 1 < n else 0))

        for i in range(n):
            for j in range(i + 2, n + 1):
                cost = a * (j - 1 - i) + prefix[i] + suffix[j]
                if j - 1 - i >= n:
                    cost = a * n
                min_cost = min(min_cost, cost)
                if min_cost == 0:
                    return "0"

