import sys

def solution(input_str):
    n, k, m = map(int, input_str.split())
    MOD = 10**9 + 7

    if k == 1:
        # If k=1, we just choose any starting planet
        return str(n % MOD)

    sys.setrecursionlimit(50000)

    def dfs(current, depth, visited):
        if depth == k:
            return 1

        count = 0
        # Next planet must be in [1, min(n, current + m)] and not visited
        for nxt in range(max(1, current - m), min(n, current + m + 1)):
            if nxt not in visited:
                visited.add(nxt)
                count += dfs(nxt, depth + 1, visited)
                visited.remove(nxt)

        return count

    total = 0
    for start in range(1, n + 1):
        visited = {start}
        total = (total + dfs(start, 1, visited)) % MOD

    return str(total)

